// Detect Key (special) game (game) (run without screen refresh)
void Glue3DSprite::DetectKeyGame(Value special, Value game)
{
    stage.inputSubmit = 0;
    stage.inputIndex = 1;
    stage.inputKey = u""_s;
    while (!(Gt(stage.inputIndex, stage.keys.Length() + 1) || (((!KeyPressed(u""_s + u","_s)) || Eq(special, 1)) && (Gt(stage.inputIndex, 39 * Num(Eq(special, 0)) + (Num(Eq(special, 1)) * stage.keys.Length())) || KeyPressed(stage.keys.Item(stage.inputIndex))))))
    {
        stage.inputIndex = stage.inputIndex.Num() + 1;
    }
    if (KeyPressed(stage.keys.Item(stage.inputIndex)))
    {
        stage.inputKey = stage.keys.Item(stage.inputIndex);
    }
    if (Eq(game, u""_s))
    {
        if (KeyPressed(u"space"_s))
        {
            if (Eq(special, 1))
            {
                stage.inputKey = u" "_s;
            }
            else
            {
                stage.inputKey = u"-"_s;
            }
        }
        if (Eq(special, 0))
        {
            if (KeyPressed(u"left arrow"_s) || KeyPressed(u"backspace"_s + u""_s))
            {
                stage.inputDelete = u""_s;
                stage.inputIndex = 0;
                for (double i1 = 0, times1 = Round(stage.ramEngineData.Item((stage.inputAddress.Num() - 1) * 2 + 2).Str().Length() - 1); i1 < times1; i1++)
                {
                    stage.inputIndex = stage.inputIndex.Num() + 1;
                    stage.inputDelete = stage.inputDelete.Str() + LetterOf(stage.inputIndex.Num(), stage.ramEngineData.Item((stage.inputAddress.Num() - 1) * 2 + 2).Str());
                }
                EditAddress(stage.inputAddress, stage.inputDelete);
            }
            else if (KeyPressed(u"enter"_s + u""_s))
            {
                stage.inputSubmit = 1;
            }
            else if (Lt(stage.ramEngineData.Item((stage.inputAddress.Num() - 1) * 2 + 2).Str().Length(), stage.inputLimit.Num() + 1))
            {
                EditAddress(stage.inputAddress, stage.ramEngineData.Item((stage.inputAddress.Num() - 1) * 2 + 2).Str() + stage.inputKey.Str());
            }
            else
            {
                StartSound(u"Windows Vista Beta Exclamation"_s);
            }
        }
    }
    else
    {
        if (KeyPressed(u"up arrow"_s))
        {
            stage.inputKey = u"up"_s;
        }
        if (KeyPressed(u"down arrow"_s))
        {
            stage.inputKey = u"down"_s;
        }
        if (KeyPressed(u"right arrow"_s))
        {
            stage.inputKey = u"right"_s;
        }
        if (KeyPressed(u"left arrow"_s))
        {
            stage.inputKey = u"left"_s;
        }
        if (KeyPressed(u"space"_s))
        {
            stage.inputKey = u"space"_s;
        }
    }
}

