            stage.tempTemp1 = stage.engineOldy;
            stage.engineOldy = stage.tempTemp1.Num() * Nz(Cos(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num())) - ((stage.engineNewz.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 3).Num()) * Nz(Sin(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num())));
            stage.engineOldz = stage.tempTemp1.Num() * Nz(Sin(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num())) + ((stage.engineNewz.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 3).Num()) * Nz(Cos(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num())));
            stage.tempTemp1 = stage.engineOldx;
            stage.engineOldx = stage.tempTemp1.Num() * Nz(Cos(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num())) - (stage.engineOldz.Num() * Nz(Sin(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num())));
            stage.engineOldz = stage.tempTemp1.Num() * Nz(Sin(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num())) + (stage.engineOldz.Num() * Nz(Cos(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num())));
            stage.engineNewx = stage.engineOldx.Num() + stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 1).Num();
            stage.engineNewy = stage.engineOldy.Num() + stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 2).Num();
            stage.engineNewz = stage.engineOldz.Num() + stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 3).Num();
            stage.engineBoneidx1 = stage.engineBoneidx1.Num() + 1;
