            stage.engineFilldistance1 = (stage.engineRes.Num() + 0.15) * (stage.engineFilldistance1.Num() * Num(Gt(stage.engineFilldistance1.Num() + 0.0001, stage.engineFilldistance2)) + (stage.engineFilldistance2.Num() * Num(Lt(stage.engineFilldistance1.Num() + 0.0001, stage.engineFilldistance2))));
            stage.engineFillstepx1 = (stage.loadedQuadPoints.Item(7).Num() - stage.engineFillx1.Num()) / stage.engineFilldistance1.Num();
