// engine.project_point (zbuffer) (x) (y) (z) bone (BoneModel) (BoneParent) boneloaded (boneloaded) (run without screen refresh)
void Glue3DSprite::EngineProjectPointZbufferBoneBoneloaded(Value x, Value y, Value z, Value boneModel, Value boneParent, Value boneloaded)
{
    if (Eq(stage.engineClip, 0))
    {
        if ((Eq(boneloaded, 1) && Gt(boneModel, u""_s)) && (!Eq(boneParent, 0)))
        {
            stage.temp.DeleteAll();
            stage.indexCounter = 0;
            stage.engineBoneparent = stage.loadedBoneTree.IndexOf(boneParent.Str() + (u".b-"_s + boneModel.Str())) - 8;
            stage.engineBoneindex = stage.engineBoneparent;
            stage.temp.Add(stage.engineBoneparent);
            while (!((Eq(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 7), 0) || Eq(stage.loadedBoneTree.Item(stage.engineBoneindex.Num() + 7), 0)) || Gt(stage.indexCounter, 100)))
            {
                stage.engineBoneindex = stage.loadedBoneTree.IndexOf(stage.loadedBoneTree.Item(stage.engineBoneindex.Num() + 7).Str() + (u".b-"_s + boneModel.Str())) - 8;
                stage.temp.Add(stage.engineBoneindex);
                stage.indexCounter = stage.indexCounter.Num() + 1;
            }
            stage.engineNewx = x;
            stage.engineNewy = y;
            stage.engineNewz = z;
            stage.engineBoneidx1 = 1;
            for (double i1 = 0, times1 = Round(stage.temp.Length()); i1 < times1; i1++)
            {
                stage.engineBoneparent = stage.temp.Item(stage.engineBoneidx1);
                stage.engineOldx = (stage.engineNewx.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 1).Num()) * Nz(Cos(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num())) - ((stage.engineNewy.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 2).Num()) * Nz(Sin(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num())));
                stage.engineOldy = (stage.engineNewx.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 1).Num()) * Nz(Sin(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num())) + ((stage.engineNewy.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 2).Num()) * Nz(Cos(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num())));
                stage.tempTemp1 = stage.engineOldy;
                stage.engineOldy = stage.tempTemp1.Num() * Nz(Cos(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num())) - ((stage.engineNewz.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 3).Num()) * Nz(Sin(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num())));
                stage.engineOldz = stage.tempTemp1.Num() * Nz(Sin(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num())) + ((stage.engineNewz.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 3).Num()) * Nz(Cos(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num())));
                stage.tempTemp1 = stage.engineOldx;
                stage.engineOldx = stage.tempTemp1.Num() * Nz(Cos(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num())) - (stage.engineOldz.Num() * Nz(Sin(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num())));
                stage.engineOldz = stage.tempTemp1.Num() * Nz(Sin(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num())) + (stage.engineOldz.Num() * Nz(Cos(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num())));
                stage.engineNewx = stage.engineOldx.Num() + stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 1).Num();
                stage.engineNewy = stage.engineOldy.Num() + stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 2).Num();
                stage.engineNewz = stage.engineOldz.Num() + stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 3).Num();
                stage.engineBoneidx1 = stage.engineBoneidx1.Num() + 1;
            }
            stage.engineOldx = stage.engineNewx.Num() * stage.engineScalex.Num();
            stage.engineOldy = (stage.engineNewy.Num() + 0.5) * stage.engineScaley.Num() - 0.5;
            stage.engineOldz = stage.engineNewz.Num() * stage.engineScalez.Num();
        }
        else
        {
            stage.engineOldx = x.Num() * stage.engineScalex.Num();
            stage.engineOldy = (y.Num() + 0.5) * stage.engineScaley.Num() - 0.5;
            stage.engineOldz = z.Num() * stage.engineScalez.Num();
        }
        stage.tempTemp1 = stage.engineOldx;
        stage.engineOldx = Nz(Cos(stage.engineGlobalrz.Num())) * stage.tempTemp1.Num() - (Nz(Sin(stage.engineGlobalrz.Num())) * stage.engineOldy.Num());
        stage.engineOldy = Nz(Sin(stage.engineGlobalrz.Num())) * stage.tempTemp1.Num() + (Nz(Cos(stage.engineGlobalrz.Num())) * stage.engineOldy.Num());
        stage.engineNewx = stage.engineOldx;
        stage.engineNewy = stage.engineOldy;
        stage.engineOldy = Nz(Cos(stage.engineGlobalry.Num())) * stage.engineNewy.Num() - (Nz(Sin(stage.engineGlobalry.Num())) * stage.engineOldz.Num());
        stage.engineOldz = Nz(Sin(stage.engineGlobalry.Num())) * stage.engineNewy.Num() + (Nz(Cos(stage.engineGlobalry.Num())) * stage.engineOldz.Num());
        stage.engineNewz = stage.engineOldz;
        stage.engineOldx = Nz(Cos(stage.engineGlobalrx.Num())) * stage.engineNewx.Num() - (Nz(Sin(stage.engineGlobalrx.Num())) * stage.engineNewz.Num());
        stage.engineOldz = Nz(Sin(stage.engineGlobalrx.Num())) * stage.engineNewx.Num() + (Nz(Cos(stage.engineGlobalrx.Num())) * stage.engineNewz.Num());
        stage.engineNewx = stage.engineCamxcos.Num() * (stage.engineOldx.Num() + stage.engineGlobalx.Num() - stage.engineCameraX.Num()) - (stage.engineCamxsin.Num() * (stage.engineOldz.Num() + stage.engineGlobalz.Num() - stage.engineCameraZ.Num()));
        stage.engineNewy = stage.engineOldy.Num() + stage.engineGlobaly.Num() - stage.engineCameraY.Num();
        stage.engineNewz = stage.engineCamxsin.Num() * (stage.engineOldx.Num() + stage.engineGlobalx.Num() - stage.engineCameraX.Num()) + (stage.engineCamxcos.Num() * (stage.engineOldz.Num() + stage.engineGlobalz.Num() - stage.engineCameraZ.Num()));
        if (Gt(stage.engineNewz, 0.5))
        {
            stage.loadedQuadPoints.Add(stage.engineNewx.Num() * Nz(stage.engineFov.Num() / stage.engineNewz.Num()));
            stage.loadedQuadPoints.Add(stage.engineNewy.Num() * Nz(stage.engineFov.Num() / stage.engineNewz.Num()) - (stage.engineCameraDirY.Num() * 3));
            stage.loadedQuadPoints.Add(stage.engineNewz.Num() / stage.engineFov.Num());
            if (Gt(std::fabs(stage.loadedQuadPoints.Item(stage.loadedQuadPoints.Length() - 2).Num()), 480) || Gt(std::fabs(stage.loadedQuadPoints.Item(stage.loadedQuadPoints.Length() - 1).Num()), 480))
            {
                stage.engineClip = 1;
            }
        }
        else
        {
            stage.engineClip = 1;
        }
    }
}

