                    {
                        EngineTileEditorCreatetileHeightTexture(stage.modelCursorx.Num() + 4, stage.modelCursory, stage.modelCursorz, stage.modelHeight, stage.modelTexture, stage.modelTexturedat, stage.modelTool);
                    }
