// Edit data in object (Object name) data (data name) (data val) operation (operation) (run without screen refresh)
void Glue3DSprite::EditDataInObjectDataOperation(Value objectName, Value dataName, Value dataVal, Value operation)
{
    stage.sceneObject = stage.scene.IndexOf(objectName.Str() + u".start"_s) - 1;
    stage.dataReturn = u"null"_s;
    for (double i1 = 0, times1 = Round(100); i1 < times1; i1++)
    {
        stage.sceneObject = stage.sceneObject.Num() + 2;
        if (Eq(stage.scene.Item(stage.sceneObject), objectName.Str() + u".end"_s)) break; // EDITED: only this object's variables
        if (Eq(stage.scene.Item(stage.sceneObject), dataName))
        {
            if (Eq(operation, u"set"_s))
            {
                stage.scene.Replace(stage.sceneObject.Num() + 1, dataVal);
                stage.dataReturn = stage.scene.Item(stage.sceneObject.Num() + 1);
            }
            else if (Eq(operation, u"add"_s))
            {
                stage.scene.Replace(stage.sceneObject.Num() + 1, stage.scene.Item(stage.sceneObject.Num() + 1).Num() + dataVal.Num());
                stage.dataReturn = stage.scene.Item(stage.sceneObject.Num() + 1);
            }
            else if (Eq(operation, u"mul"_s))
            {
                stage.scene.Replace(stage.sceneObject.Num() + 1, stage.scene.Item(stage.sceneObject.Num() + 1).Num() * dataVal.Num());
                stage.dataReturn = stage.scene.Item(stage.sceneObject.Num() + 1);
            }
            else if (Eq(operation, u"read"_s))
            {
                stage.dataReturn = stage.scene.Item(stage.sceneObject.Num() + 1);
            }
            return;
        }
    }
    if (!Eq(operation, u"read"_s))
    {
        TerminalPrint(u"variable \""_s + (dataName.Str() + (u"\" not found in "_s + objectName.Str())), 0);
    }
}

