// autocomplete proccessor (run without screen refresh)
#ifndef GLUE3D_PLAYER // editor only: a built game never runs this (tools/glue3d_edits.py)
void Glue3DSprite::AutocompleteProccessor()
{
    stage.autocompleteLine.DeleteAll();
    if (Eq(stage.loadedTextEditor.Item(stage.textCursory.Num() + 1), u""_s))
    {
        stage.textAutocompleteguess = u""_s;
        stage.textAutocomplete = u"main"_s;
    }
    else
    {
        DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.loadedTextEditor.Item(stage.textCursory.Num() + 1), u""_s, u". "_s, u""_s, u""_s);
        stage.textAutocompleteindex = 1;
        for (double i1 = 0, times1 = Round(stage.decodedElements.Length() - 0); i1 < times1; i1++)
        {
            if (Gt(stage.decodedElements.Item(stage.textAutocompleteindex), u""_s))
            {
                stage.autocompleteLine.Add(stage.decodedElements.Item(stage.textAutocompleteindex));
            }
            stage.textAutocompleteindex = stage.textAutocompleteindex.Num() + 1;
        }
        stage.textAutocompleteguess = stage.autocompleteLine.Item(stage.autocompleteLine.Length());
        if (!Eq(stage.textAutocompleteguess, stage.textAutocompletetick))
        {
            if (stage.autocomplete.Contains(stage.textAutocompleteguess.Str() + u".start"_s) && Gt(stage.autocompleteLine.Length(), 0))
            {
                StartSound(u"Windows Navigation Start3"_s);
                stage.textAutocomplete = stage.textAutocompleteguess;
            }
        }
        stage.textAutocompletetick = stage.textAutocompleteguess;
    }
}
#else
void Glue3DSprite::AutocompleteProccessor() {}
#endif

