// glue3d.run (run without screen refresh)
void Glue3DSprite::Glue3dRun()
{
    if (Eq(stage.allRun, 0))
    {
        AllLoadscripts();
        ResetTimer();
        stage.timeTimer = Timer();
        stage.guiClickedelement = u""_s;
        stage.engineForcefreecam = 0;
        stage.allRun = 1;
        stage.objectIndex = 0;
        stage.allClock = 0;
        stage.allTime = 0;
        stage.guiInteract = 1;
        stage.allCycle = stage.allCycle.Num() + 1;
        stage.timeDelta = 0;
        stage.loadedBoneTree.DeleteAll();
        stage.loadedBoneTree.Add(0);
        stage.terminal.DeleteAll();
        stage.tempScene.DeleteAll();
        stage.programloops.DeleteAll();
        stage.tempFiles.DeleteAll();
        for (double i1 = 0, times1 = Round(stage.scene.Length()); i1 < times1; i1++)
        {
            stage.objectIndex = stage.objectIndex.Num() + 1;
            stage.tempScene.Add(stage.scene.Item(stage.objectIndex));
        }
    }
}

// glue3d.stop (run without screen refresh)
void Glue3DSprite::Glue3dStop()
{
    if (Eq(stage.allRun, 1))
    {
        ClearSoundEffects();
        StopAllSounds();
        stage.allStereo = 1;
        stage.allRun = 0;
        stage.objectIndex = 0;
        stage.loadedBoneTree.DeleteAll();
        stage.loadedBoneTree.Add(0);
        stage.loadedScripts.DeleteAll();
        stage.soundTab.DeleteAll();
        stage.scene.DeleteAll();
        for (double i1 = 0, times1 = Round(stage.tempScene.Length()); i1 < times1; i1++)
        {
            stage.objectIndex = stage.objectIndex.Num() + 1;
            stage.scene.Add(stage.tempScene.Item(stage.objectIndex));
        }
        stage.tempScene.DeleteAll();
        stage.engineCamera = u"free"_s;
        stage.ramEngineData.Replace(112, stage.engineOldcamx);
        stage.ramEngineData.Replace(114, stage.engineOldcamy);
        stage.ramEngineData.Replace(116, stage.engineOldcamz);
        stage.ramEngineData.Replace(118, stage.engineOldcamdirx);
        stage.ramEngineData.Replace(120, stage.engineOldcamdiry);
        stage.ramEngineData.Replace(122, stage.engineOldcamdirz);
        stage.indexIndex1 = 1;
        for (double i1 = 0, times1 = Round(stage.tempFiles.Length()); i1 < times1; i1++)
        {
            if (Gt(stage.engineFiles.IndexOf(stage.tempFiles.Item(stage.indexIndex1)), 0))
            {
                DeleteNameIfDataObject(u"file"_s, stage.engineFiles.IndexOf(stage.tempFiles.Item(stage.indexIndex1)), u""_s, u""_s);
            }
            stage.indexIndex1 = stage.indexIndex1.Num() + 1;
        }
        stage.tempFiles.DeleteAll();
    }
}

// Glue3d.Execute (run without screen refresh)
void Glue3DSprite::Glue3dExecute()
{
    if (Eq(stage.allRun, 1))
    {
        stage.timeClockSpeed = 1 + stage.ramEngineData.Item(210).Num();
        stage.allClock = stage.allClock.Num() + 1;
        stage.timeCpuCycle = 1;
        stage.allTime = stage.allTime.Num() + stage.timeDelta.Num();
        stage.objectIndex = 2;
        for (double i1 = 0, times1 = Round(stage.scene.Item(1).Num()); i1 < times1; i1++)
        {
            stage.scriptExit = 0;
            stage.scriptHeader = stage.loadedScripts.IndexOf(stage.scene.Item(stage.objectIndex.Num() + 29).Str() + u".start"_s);
            stage.scriptEnd = stage.loadedScripts.IndexOf(stage.scene.Item(stage.objectIndex.Num() + 29).Str() + u".end"_s);
            if (Eq(stage.scene.Item(stage.objectIndex.Num() + 7), u"elementui"_s) && Eq(stage.allClock, 1))
            {
                InsertDataToObjectData(stage.scene.Item(stage.objectIndex.Num() + 3), u"ui-id"_s, u"_icon.empty"_s);
                InsertDataToObjectData(stage.scene.Item(stage.objectIndex.Num() + 3), u"ui-clickable"_s, u"false"_s);
                InsertDataToObjectData(stage.scene.Item(stage.objectIndex.Num() + 3), u"ui-text"_s, u""_s);
                InsertDataToObjectData(stage.scene.Item(stage.objectIndex.Num() + 3), u"ui-ghost"_s, u""_s);
            }
            for (double i2 = 0, times2 = Round((8 * (1 - stage.timeClockMode.Num()) + ((stage.scriptEnd.Num() - stage.scriptHeader.Num()) * (stage.timeClockMode.Num() * 0.8))) * (stage.timeClockSpeed.Num() * 1.5)); i2 < times2; i2++)
            {
                stage.timeScriptclock = (stage.scriptEnd.Num() - stage.scriptHeader.Num() - 1) * stage.timeClockSpeed.Num();
                if (Eq(stage.scriptExit, 0) && (!(Eq(stage.scene.Item(stage.objectIndex.Num() + 29), u""_s) || Eq(stage.scene.Item(stage.objectIndex.Num() + 31), u"halt"_s))) && !ScriptPaused()) /* EDITED: game.pause */
                {
                    stage.terminalHeader = stage.terminal.Length() + 1;
                    stage.terminalMessage = 0;
                    RunLineMainObjectScript(stage.scene.Item(stage.objectIndex.Num() + 31), stage.scene.Item(stage.objectIndex.Num() + 3), stage.scene.Item(stage.objectIndex.Num() + 29));
                    if (Eq(stage.scriptExit, 0) && (Lt(stage.scene.Item(stage.objectIndex.Num() + 35), 0.0125) && (!Eq(stage.scene.Item(stage.objectIndex.Num() + 31), u"halt"_s))))
                    {
                        stage.scene.Replace(stage.objectIndex.Num() + 31, stage.scene.Item(stage.objectIndex.Num() + 31).Num() + 1);
                        stage.scene.Replace(stage.objectIndex.Num() + 37, 0);
                    }
                }
            }
            if (Eq(stage.scriptExit, 0))
            {
                stage.objectIndex = stage.objectIndex.Num() + stage.scene.Item(stage.objectIndex).Num();
            }
        }
        stage.timeCpuCycle = stage.timeCpuCycle.Num() + 1;
    }
}

// Run Line (clock) main object (object) script (script) (run without screen refresh)
void Glue3DSprite::RunLineMainObjectScript(Value clock, Value object, Value script)
{
    stage.scriptReadindex = 1 + (stage.scriptHeader.Num() + clock.Num());
    stage.scriptLine = stage.loadedScripts.Item(stage.scriptReadindex);
    stage.scriptObject = object;
    stage.scriptName = script;
    if (!((Eq(stage.scriptLine, script.Str() + u".end"_s) || Eq(stage.scriptLine, u""_s)) || (Eq(LetterOf(2, stage.scriptLine.Str()), u"/"_s) && Eq(LetterOf(1, stage.scriptLine.Str()), u"/"_s))))
    {
        DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.scriptLine.Str() + u" "_s, u""_s, u" (),"_s, u""_s, u"."_s);
        if (CustomCommand()) return; // EDITED: GluePP's extra blocks (Custom/ScriptBlocks.cpp)
        if (Eq(stage.decodedElements.Item(1), u"object"_s))
        {
            ProccessObject();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"model"_s))
        {
            ProccessModel();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"math"_s))
        {
            ProccessMath();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"var"_s))
        {
            ProccessVariable();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"physics"_s))
        {
            ProccessPhysics();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"game"_s))
        {
            ProccessGame();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"terminal"_s))
        {
            ProccessTerminal();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"sound"_s))
        {
            ProccessSound();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"interface"_s))
        {
            ProccessInterface();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"file"_s))
        {
            ProccessFile();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"time"_s))
        {
            ProccessTime();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"editor"_s))
        {
            ProccessEditor();
            return;
        }
        if (Eq(stage.decodedElements.Item(1), u"list"_s))
        {
            ProccessList();
            return;
        }
        ProccessOther();
    }
    else if (Eq(stage.scriptLine, script.Str() + u".end"_s))
    {
        TerminalPrint(u"finished code"_s, -35);
        stage.scene.Replace(stage.objectIndex.Num() + 31, u"halt"_s);
    }
}

// proccess.object (run without screen refresh)
void Glue3DSprite::ProccessObject()
{
    DataRecall();
    if (Eq(stage.decodedElements.Item(2), u"edit_data"_s))
    {
        EditDataInObjectDataOperation(stage.dataVal1, stage.dataVal2, stage.dataVal3, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"distance"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, 0, u"read"_s);
        stage.gameX = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, 0, u"read"_s);
        stage.gameY = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, 0, u"read"_s);
        stage.gameZ = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"x"_s, 0, u"read"_s);
        stage.gameFollowX = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"y"_s, 0, u"read"_s);
        stage.gameFollowY = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"z"_s, 0, u"read"_s);
        stage.gameFollowZ = stage.dataReturn;
        stage.dataVal1 = std::sqrt((stage.gameX.Num() - stage.gameFollowX.Num()) * (stage.gameX.Num() - stage.gameFollowX.Num()) + ((stage.gameY.Num() - stage.gameFollowY.Num()) * (stage.gameY.Num() - stage.gameFollowY.Num()) + ((stage.gameZ.Num() - stage.gameFollowZ.Num()) * (stage.gameZ.Num() - stage.gameFollowZ.Num()))));
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, stage.dataVal1, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"get_data"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.dataVal1, stage.dataVal2, 0, u"read"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, stage.dataReturn, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"rotate_toward"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, u"-"_s, u"read"_s);
        stage.gameDirx = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"x"_s, u"-"_s, u"read"_s);
        stage.gameDiry = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"z"_s, u"-"_s, u"read"_s);
        stage.gameDirz = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, u"-"_s, u"read"_s);
        stage.gameX = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, u"-"_s, u"read"_s);
        stage.gameY = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, (0 - (Atan(Nz((stage.gameDiry.Num() - stage.gameX.Num()) / (stage.gameDirz.Num() - stage.gameY.Num()))) + (180 * Num(Gt(stage.gameY, stage.gameDirz)))) - stage.gameDirx.Num()) / stage.dataVal2.Num(), u"add"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"turn"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, stage.dataVal1, u"add"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"ry"_s, stage.dataVal2, u"add"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"rz"_s, stage.dataVal3, u"add"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"move_dir"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, Nz(Cos(stage.dataVal1.Num() + 90)) * stage.dataVal2.Num(), u"add"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, Nz(Sin(stage.dataVal1.Num() + 90)) * stage.dataVal2.Num(), u"add"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"move"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, stage.dataVal1, u"add"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, stage.dataVal2, u"add"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, stage.dataVal3, u"add"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"rotate_to"_s))
    {
        if (Eq(stage.dataVal4, 1))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, stage.dataVal1, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"ry"_s, stage.dataVal2, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"rz"_s, stage.dataVal3, u"set"_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, u""_s, u"read"_s);
            stage.tempA1 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, (stage.dataVal1.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"ry"_s, u""_s, u"read"_s);
            stage.tempA2 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"ry"_s, (stage.dataVal2.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"rz"_s, u""_s, u"read"_s);
            stage.tempA3 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"rz"_s, (stage.dataVal3.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            if (Eq(stage.scene.Item(stage.objectIndex.Num() + 37), 0))
            {
                stage.scene.Replace(stage.objectIndex.Num() + 35, u"A"_s);
                stage.scene.Replace(stage.objectIndex.Num() + 37, u"clock_distance"_s);
            }
            if (Eq(stage.scene.Item(stage.objectIndex.Num() + 37), u"clock_distance"_s))
            {
                stage.scene.Replace(stage.objectIndex.Num() + 35, (std::fabs(stage.dataVal1.Num() - stage.tempA1.Num()) + (std::fabs(stage.dataVal2.Num() - stage.tempA2.Num()) + (std::fabs(stage.dataVal3.Num() - stage.tempA3.Num())))) / 3);
            }
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"scale_to"_s))
    {
        if (Eq(stage.dataVal4, 1))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"sx"_s, stage.dataVal1, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"sy"_s, stage.dataVal2, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"sz"_s, stage.dataVal3, u"set"_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"sx"_s, u""_s, u"read"_s);
            stage.tempA1 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"sx"_s, (stage.dataVal1.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"sy"_s, u""_s, u"read"_s);
            stage.tempA2 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"sy"_s, (stage.dataVal2.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"sz"_s, u""_s, u"read"_s);
            stage.tempA3 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"sz"_s, (stage.dataVal3.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            if (Eq(stage.scene.Item(stage.objectIndex.Num() + 37), 0))
            {
                stage.scene.Replace(stage.objectIndex.Num() + 35, u"A"_s);
                stage.scene.Replace(stage.objectIndex.Num() + 37, u"clock_distance"_s);
            }
            if (Eq(stage.scene.Item(stage.objectIndex.Num() + 37), u"clock_distance"_s))
            {
                stage.scene.Replace(stage.objectIndex.Num() + 35, (std::fabs(stage.dataVal1.Num() - stage.tempA1.Num()) + (std::fabs(stage.dataVal2.Num() - stage.tempA2.Num()) + (std::fabs(stage.dataVal3.Num() - stage.tempA3.Num())))) / 3);
            }
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"go_to_object"_s))
    {
        stage.dataVal4 = stage.dataVal2;
        EditDataInObjectDataOperation(stage.dataVal1, u"z"_s, u"-"_s, u"read"_s);
        stage.dataVal3 = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"y"_s, u"-"_s, u"read"_s);
        stage.dataVal2 = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"x"_s, u"-"_s, u"read"_s);
        stage.dataVal1 = stage.dataReturn;
        if (Eq(stage.dataVal4, 1))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, stage.dataVal1, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, stage.dataVal2, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, stage.dataVal3, u"set"_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, u""_s, u"read"_s);
            stage.tempA1 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, (stage.dataVal1.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, u""_s, u"read"_s);
            stage.tempA2 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, (stage.dataVal2.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, u""_s, u"read"_s);
            stage.tempA3 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, (stage.dataVal3.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            if (Eq(stage.scene.Item(stage.objectIndex.Num() + 37), 0))
            {
                stage.scene.Replace(stage.objectIndex.Num() + 35, u"A"_s);
                stage.scene.Replace(stage.objectIndex.Num() + 37, u"clock_distance"_s);
            }
            if (Eq(stage.scene.Item(stage.objectIndex.Num() + 37), u"clock_distance"_s))
            {
                stage.scene.Replace(stage.objectIndex.Num() + 35, (std::fabs(stage.dataVal1.Num() - stage.tempA1.Num()) + (std::fabs(stage.dataVal2.Num() - stage.tempA2.Num()) + (std::fabs(stage.dataVal3.Num() - stage.tempA3.Num())))) / 3);
            }
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"go_to"_s))
    {
        if (Eq(stage.dataVal4, 1))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, stage.dataVal1, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, stage.dataVal2, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, stage.dataVal3, u"set"_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, u""_s, u"read"_s);
            stage.tempA1 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, (stage.dataVal1.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, u""_s, u"read"_s);
            stage.tempA2 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, (stage.dataVal2.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, u""_s, u"read"_s);
            stage.tempA3 = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, (stage.dataVal3.Num() - stage.dataReturn.Num()) / (stage.dataVal4.Num() * stage.timeClockSpeed.Num() + 1), u"add"_s);
            if (Eq(stage.scene.Item(stage.objectIndex.Num() + 37), 0))
            {
                stage.scene.Replace(stage.objectIndex.Num() + 35, u"A"_s);
                stage.scene.Replace(stage.objectIndex.Num() + 37, u"clock_distance"_s);
            }
            if (Eq(stage.scene.Item(stage.objectIndex.Num() + 37), u"clock_distance"_s))
            {
                stage.scene.Replace(stage.objectIndex.Num() + 35, (std::fabs(stage.dataVal1.Num() - stage.tempA1.Num()) + (std::fabs(stage.dataVal2.Num() - stage.tempA2.Num()) + (std::fabs(stage.dataVal3.Num() - stage.tempA3.Num())))) / 3);
            }
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"delete"_s))
    {
        DeleteNameIfDataObject(u""_s, u""_s, u""_s, stage.scene.IndexOf(stage.scriptObject.Str() + u".start"_s) - 1);
        stage.scriptExit = 1;
    }
    if (Eq(stage.decodedElements.Item(2), u"clone"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, u"-"_s, u"read"_s);
        stage.gameX = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, u"-"_s, u"read"_s);
        stage.gameY = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, u"-"_s, u"read"_s);
        stage.gameZ = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, u"-"_s, u"read"_s);
        stage.gameDirx = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"ry"_s, u"-"_s, u"read"_s);
        stage.gameDiry = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"rz"_s, u"-"_s, u"read"_s);
        stage.gameDirz = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"model"_s, u"-"_s, u"read"_s);
        stage.gameModel = stage.dataReturn;
        stage.objectName = LetterOf(1, stage.scriptObject.Str()) + LetterOf(2, stage.scriptObject.Str()) + (u"_"_s + Str(PickRandom(1, 99999)));
        CreateObjectTypeModelOnRotationScript(stage.objectName, u"3d"_s, stage.gameModel, stage.gameX, stage.gameY, stage.gameZ, stage.gameDirx, stage.gameDiry, stage.gameDirz, stage.dataVal1);
        EditDataInObjectDataOperation(stage.scriptObject, u"sx"_s, u"-"_s, u"read"_s);
        EditDataInObjectDataOperation(stage.objectName, u"sx"_s, stage.dataReturn, u"set"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"sy"_s, u"-"_s, u"read"_s);
        EditDataInObjectDataOperation(stage.objectName, u"sy"_s, stage.dataReturn, u"set"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"sz"_s, u"-"_s, u"read"_s);
        EditDataInObjectDataOperation(stage.objectName, u"sz"_s, stage.dataReturn, u"set"_s);
    }
}

// proccess.model (run without screen refresh)
void Glue3DSprite::ProccessModel()
{
    DataRecall();
    if (Eq(stage.decodedElements.Item(2), u"set_model"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"model"_s, stage.dataVal1, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"refresh_models"_s))
    {
        stage.loadedModels.DeleteAll();
        stage.loadedModels.Add(0);
        EngineRefreshRenderQueue();
    }
    if (Eq(stage.decodedElements.Item(2), u"set_bone"_s))
    {
        FileFindData(stage.dataVal1);
        if (Eq(stage.fileFound, 1))
        {
            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), 1, u""_s, u""_s, u""_s);
            EngineLoad3dModelBone(stage.decodedElements.Item(1), 1, u"."_s + stage.scriptObject.Str());
            EditDataInObjectDataOperation(stage.scriptObject, u"bone"_s, stage.dataVal1, u"set"_s);
            InsertDataToObjectData(stage.scriptObject, u"bone_ease"_s, 1);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"ease"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"bone_ease"_s, stage.dataVal1, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"rotate_bone"_s) || Eq(stage.decodedElements.Item(2), u"turn_bone"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"bone_ease"_s, 0, u"read"_s);
        stage.modelBoneease = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"bone"_s, 0, u"read"_s);
        stage.engineBoneparent = stage.loadedBoneTree.IndexOf(stage.dataVal4.Str() + (u".b-"_s + (stage.dataReturn.Str() + (u"."_s + stage.scriptObject.Str())))) - 8;
        if (Eq(stage.decodedElements.Item(2), u"rotate_bone"_s))
        {
            if (Eq(stage.modelBoneease, 0))
            {
                stage.loadedBoneTree.Replace(stage.engineBoneparent.Num() + 4, stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num() + Nz((stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num() + (10 * (Num(!Eq(std::floor(Nz(stage.dataVal1.Num() / 2)), std::floor(Nz(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num() / 5)))) * (1 - (Num(Lt(stage.dataVal1, stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4))) * 2)))) - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num()) / 3));
                stage.loadedBoneTree.Replace(stage.engineBoneparent.Num() + 5, stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num() + Nz((stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num() + (10 * (Num(!Eq(std::floor(Nz(stage.dataVal2.Num() / 5)), std::floor(Nz(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num() / 5)))) * (1 - (Num(Lt(stage.dataVal2, stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5))) * 2)))) - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num()) / 3));
                stage.loadedBoneTree.Replace(stage.engineBoneparent.Num() + 6, stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num() + Nz((stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num() + (10 * (Num(!Eq(std::floor(Nz(stage.dataVal3.Num() / 5)), std::floor(Nz(stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num() / 5)))) * (1 - (Num(Lt(stage.dataVal3, stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6))) * 2)))) - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num()) / 3));
            }
            else
            {
                stage.loadedBoneTree.Replace(stage.engineBoneparent.Num() + 4, stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num() + Nz((stage.dataVal1.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num()) / stage.modelBoneease.Num()));
                stage.loadedBoneTree.Replace(stage.engineBoneparent.Num() + 5, stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num() + Nz((stage.dataVal2.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num()) / stage.modelBoneease.Num()));
                stage.loadedBoneTree.Replace(stage.engineBoneparent.Num() + 6, stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num() + Nz((stage.dataVal3.Num() - stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num()) / stage.modelBoneease.Num()));
            }
        }
        else
        {
            stage.loadedBoneTree.Replace(stage.engineBoneparent.Num() + 4, stage.dataVal1.Num() + stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 4).Num());
            stage.loadedBoneTree.Replace(stage.engineBoneparent.Num() + 5, stage.dataVal2.Num() + stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 5).Num());
            stage.loadedBoneTree.Replace(stage.engineBoneparent.Num() + 6, stage.dataVal3.Num() + stage.loadedBoneTree.Item(stage.engineBoneparent.Num() + 6).Num());
        }
    }
}

// proccess.game (run without screen refresh)
void Glue3DSprite::ProccessGame()
{
    DataRecall();
    if (Eq(stage.decodedElements.Item(2), u"include_game"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"game"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"game"_s, 0);
            InsertDataToObjectData(stage.scriptObject, u"movement_type"_s, u"human"_s);
        }
        else
        {
            TerminalPrint(u"game already included!"_s, u""_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"movement_type"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"game"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            TerminalPrint(u"game not included!"_s, u""_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"movement_type"_s, stage.dataVal1, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"set_camera"_s))
    {
        stage.engineGamecamera = stage.dataVal1;
    }
    if (Eq(stage.decodedElements.Item(2), u"camera_1st"_s))
    {
        EditDataInObjectDataOperation(stage.dataVal1, u"x"_s, u"-"_s, u"read"_s);
        stage.gameFollowX = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"y"_s, u"-"_s, u"read"_s);
        stage.gameFollowY = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"z"_s, u"-"_s, u"read"_s);
        stage.gameFollowZ = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"rx"_s, u"-"_s, u"read"_s);
        stage.gameFollowDirx = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"ry"_s, u"-"_s, u"read"_s);
        stage.gameFollowDiry = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"rz"_s, u"-"_s, u"read"_s);
        stage.gameFollowDirz = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, stage.gameFollowX, u"set"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, stage.gameFollowY.Num() + stage.dataVal2.Num(), u"set"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, stage.gameFollowZ, u"set"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, stage.gameFollowDirx, u"set"_s);
        if (false)
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"ry"_s, stage.gameFollowDiry, u"set"_s);
            EditDataInObjectDataOperation(stage.scriptObject, u"rz"_s, stage.gameFollowDirz, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"camera_3rd"_s))
    {
        stage.gameFollowDistance = stage.dataVal2;
        EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, u"-"_s, u"read"_s);
        stage.gameX = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, u"-"_s, u"read"_s);
        stage.gameY = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, u"-"_s, u"read"_s);
        stage.gameZ = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, u"-"_s, u"read"_s);
        stage.gameDirx = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"x"_s, u"-"_s, u"read"_s);
        stage.gameFollowX = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"y"_s, u"-"_s, u"read"_s);
        stage.gameFollowY = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"z"_s, u"-"_s, u"read"_s);
        stage.gameFollowZ = stage.dataReturn;
        EditDataInObjectDataOperation(stage.dataVal1, u"rx"_s, u"-"_s, u"read"_s);
        stage.gameFollowDirx = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"x"_s, (stage.gameFollowX.Num() + (stage.gameFollowDistance.Num() * Nz(Cos(stage.gameFollowDirx.Num() - 90))) - stage.gameX.Num()) / stage.dataVal3.Num(), u"add"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"y"_s, stage.gameFollowY.Num() + Nz(stage.gameFollowDistance.Num() / 3), u"set"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"z"_s, (stage.gameFollowZ.Num() + (stage.gameFollowDistance.Num() * Nz(Sin(stage.gameFollowDirx.Num() - 90))) - stage.gameZ.Num()) / stage.dataVal3.Num(), u"add"_s);
        EditDataInObjectDataOperation(stage.scriptObject, u"rx"_s, (stage.gameFollowDirx.Num() - stage.gameDirx.Num()) / stage.dataVal3.Num(), u"add"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"key_pressed"_s))
    {
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        if (KeyPressed(stage.dataVal1))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, u"true"_s, u"set"_s);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, u"false"_s, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"fov"_s))
    {
        stage.engineFov = stage.dataVal1;
    }
    if (Eq(stage.decodedElements.Item(2), u"get_key"_s))
    {
        DetectKeyGame(0, 1);
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, 0);
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, stage.inputKey, u"set"_s);
    }
    if (Eq(stage.decodedElements.Item(2), u"movement"_s))
    {
        stage.engineRequirment = 0;
        EditDataInObjectDataOperation(stage.scriptObject, u"physics"_s, u"-"_s, u"read"_s);
        stage.engineRequirment = stage.engineRequirment.Num() + (Num(!Eq(stage.dataReturn, u"null"_s)) * 1);
        EditDataInObjectDataOperation(stage.scriptObject, u"game"_s, u"-"_s, u"read"_s);
        stage.engineRequirment = stage.engineRequirment.Num() + (Num(!Eq(stage.dataReturn, u"null"_s)) * 1);
        if (Eq(stage.engineRequirment, 2))
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"movement_type"_s, u"-"_s, u"read"_s);
            // EDITED: 3rd value = controls ("arrows", "mouse", "both"), 4th = view ("left/right", "up/down", "both").
            SetGameControls(stage.dataVal3, stage.dataVal4);
            GameMoveplayer(stage.dataVal1, stage.dataVal2, stage.dataReturn);
        }
        else
        {
            TerminalPrint(u"you-need-to-include-both-\"physics\"-and-\"game\""_s, u""_s);
        }
    }
}

// proccess.math (run without screen refresh)
void Glue3DSprite::ProccessMath()
{
    if (Contains(u"add\x0621subtract\x0621multiply\x0621" u"divide\x0621modulo\x0621power\x0621sqrt\x0621" u"and\x0621or\x0621xor\x0621not\x0621greater_than\x0621less_than\x0621" u"equals\x0621random\x0621join\x0621letter\x0621"_s, stage.decodedElements.Item(2).Str() + u"\x0621"_s))
    {
        Operation(stage.decodedElements.Item(3), stage.decodedElements.Item(4), stage.decodedElements.Item(2), stage.decodedElements.Item(6), stage.decodedElements.Item(7));
        stage.mathResult = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, stage.mathResult);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, stage.mathResult, u"set"_s);
        }
    }
    if (Contains(u"abs\x0621" u"floor\x0621sin\x0621" u"cos\x0621tan\x0621" u"atan\x0621" u"asin\x0621" u"acos\x0621log\x0621not\x0621"_s, stage.decodedElements.Item(2).Str() + u"\x0621"_s))
    {
        Operation(stage.decodedElements.Item(3), stage.decodedElements.Item(4), stage.decodedElements.Item(2), u""_s, u""_s);
        stage.mathResult = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, stage.mathResult);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, stage.mathResult, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"interpolate"_s))
    {
        DataRecall();
        stage.mathResult = stage.dataVal2.Num() - Nz((stage.dataVal2.Num() - stage.dataVal1.Num()) / stage.dataVal3.Num());
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, u"-"_s, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, stage.mathResult);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, stage.mathResult, u"set"_s);
        }
    }
    if (Eq(stage.decodedElements.Item(2), u"clamp"_s))
    {
        DataRecall();
        stage.mathResult = stage.dataVal1;
        if (Lt(stage.dataVal1, stage.dataVal2))
        {
            stage.mathResult = stage.dataVal2;
        }
        else if (Gt(stage.dataVal1, stage.dataVal3))
        {
            stage.mathResult = stage.dataVal3;
        }
        EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, 0, u"read"_s);
        if (Eq(stage.dataReturn, u"null"_s))
        {
            InsertDataToObjectData(stage.scriptObject, u"data_return"_s, stage.mathResult);
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, u"data_return"_s, stage.mathResult, u"set"_s);
        }
    }
}

// proccess: terminal (run without screen refresh)
void Glue3DSprite::ProccessTerminal()
{
    DataRecall();
    if (Eq(stage.decodedElements.Item(2), u"clear"_s))
    {
        stage.terminal.DeleteAll();
    }
    if (Eq(stage.decodedElements.Item(2), u"print"_s))
    {
        if (Eq(stage.decodedElements.Item(3), u"str"_s))
        {
            TerminalPrint(stage.decodedElements.Item(4), stage.dataVal2.Num() + 15);
        }
        if (Eq(stage.decodedElements.Item(3), u"var"_s))
        {
            EditDataInObjectDataOperation(stage.scriptObject, stage.decodedElements.Item(4), u"-"_s, u"read"_s);
            if (Eq(stage.dataReturn, u"null"_s))
            {
                TerminalPrint(u"error: no variable was found"_s, u""_s);
            }
            else
            {
                TerminalPrint(stage.dataReturn, stage.dataVal2.Num() + 15);
            }
        }
        if (Eq(stage.decodedElements.Item(3), u"val"_s))
        {
            TerminalPrint(stage.decodedElements.Item(4), stage.dataVal2.Num() + 15);
        }
    }
}

